import type { Metadata } from "next";

import { QrGenerator } from "@/components/QrGenerator";
import { SiteFooter } from "@/components/SiteFooter";
import { SiteHeader } from "@/components/SiteHeader";
import { config } from "@/config";
import { toolsQr } from "@/data/content/tools-qr";
import { listActivePlacements } from "@/lib/placements";

export const metadata: Metadata = {
  title: toolsQr.title,
  robots: { index: false, follow: false },
};

/**
 * Internal QR generator (Phase 8, TQR-2).
 * Static, non-indexed, no discount banner and no QR attribution of its own —
 * the URL shape (`/l/<code>`) is the only contract shared with the funnel
 * (FR-1). Deliberately renders no `BannerInjector` so FR-15 acceptance
 * (zero discount nodes for non-QR contexts) holds trivially here.
 */
export default function QrToolsPage() {
  return (
    <>
      <SiteHeader />
      <main>
        <QrGenerator
          siteUrl={config.NEXT_PUBLIC_SITE_URL}
          activePlacements={listActivePlacements()}
        />
      </main>
      <SiteFooter />
    </>
  );
}
